function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"En la sobremesa alguien remata una discusión sobre el precio del transporte con «eso lo arregla la mano invisible, lo dijo Adam Smith». La cita es real y el autor existe."},{"txt":"Del otro lado de la mesa, y con la misma seguridad: «Adam Smith es el padre del neoliberalismo, por eso estamos así»."},{"txt":"Las tres pulperías de la colonia subieron el precio del mismo producto la misma semana, y en la casa se discute si eso es casualidad, competencia o arreglo."},{"txt":"Alguien sostiene que la idea de que los patrones se coordinan para no subir salarios es pura paranoia."},{"txt":"Jael trae para una tarea una frase de Smith que sacó de una imagen con letras bonitas y el nombre del autor abajo, sin decir de qué libro viene."},{"txt":"En la escuela se discute si los impuestos son necesarios, y Angelly pregunta qué decía sobre eso el que inventó la economía."},{"txt":"En una discusión de barrio alguien cierra el tema trayendo un nombre grande en vez de un argumento, y todos se callan."},{"txt":"Una misión de esta casa cita una frase de Smith parafraseada al español, y una familia quiere ir a buscar el texto exacto para comprobarla."}];
const critCaseQuestions=["1. Di de qué obra y de qué año es la frase, y de qué libro y capítulo si se puede. Si no aparece en ninguna de las dos obras, dilo.","2. Cuenta qué dice el párrafo completo alrededor de la frase, es decir de qué estaba hablando el autor ahí.","3. Trae la contracita: la frase del mismo autor que apunta al lado contrario, con su dirección.","4. Di qué edición o traducción se está usando, si la cita es literal o parafraseada, y qué se sigue de todo eso para lo que se estaba discutiendo."];
const critCaseGuides=["Se empieza por la dirección, que es el paso que casi nadie da y el que decide la mitad de los casos. Obra y año, y libro y capítulo si se puede: la mano invisible está en el libro IV capítulo 2 de la Riqueza de las naciones, de 1776, y aparece una sola vez. Y si la frase no se encuentra en ninguna de las dos obras, eso también es un resultado, y de los buenos: circulan atribuciones que nadie ha localizado nunca.","Después va el párrafo entero, porque casi nunca dice lo que la frase recortada sugiere. El de la mano invisible habla de que el comerciante prefiere invertir en su propio país, es decir de un argumento contra el sistema mercantil de su siglo. Una respuesta buena cuenta de qué trataba el capítulo y qué problema tenía el autor delante, no solo repite la línea.","Luego la contracita, que es la prueba de lectura de esta etapa y la parte que casi nadie escribe. Con Smith está a mano: al que trae el carnicero del libro I capítulo 2 se le pone al lado el libro I capítulo 10, donde los del mismo oficio conspiran contra el público, o el capítulo 8, donde los patrones se coordinan tácitamente para no subir salarios. Y al que trae los impuestos del libro V se le pone el carnicero. El test corta en las dos direcciones con el mismo filo.","Al final se dice qué edición se usa y si la cita es literal o parafraseada, porque de eso depende que otro pueda comprobarla: la académica es la Glasgow Edition, que Oxford publica desde 1976, y esta casa declara sus paráfrasis en vez de fingir una página. Y se cierra con lo que se sigue para la discusión que había: qué ya no se puede decir, qué queda en pie y qué habría que mirar ahora. Encima de todo va el aviso que impide el error simétrico: descubrir que a un autor lo citan mal no lo vuelve aliado de uno, y un clásico leído entero casi nunca cabe en un bando."];

const critErrorBank=[{"txt":"\"Eso lo arregla la mano invisible, lo dijo Adam Smith\".","g1":"Falta la dirección y falta el párrafo: la expresión aparece una sola vez, en el libro IV capítulo 2, y ese párrafo habla de que el comerciante prefiere invertir en su propio país.","g2":"La corrección da obra, año, libro y capítulo, cuenta de qué trata el párrafo y añade la contracita del libro I capítulo 10."},{"txt":"\"Adam Smith fue el padre del neoliberalismo\".","g1":"Es un problema de calendario antes que de ideas: Smith murió en 1790 y la palabra se acuñó y se popularizó mucho después, para nombrar políticas que él no vio.","g2":"Se corrige poniendo las fechas y remitiendo la palabra a su propio expediente, que es la etapa 6 de esta ruta."},{"txt":"\"Smith pedía impuestos a los ricos, así que estaba de nuestro lado\".","g1":"Es el error simétrico y el más dulce: el pasaje del libro V capítulo 2 existe, pero descubrir que a un autor lo citan mal no lo convierte en aliado de nadie de hoy.","g2":"Se corrige diciendo qué dice el pasaje y qué no se sigue de él, y poniendo al lado la frase del carnicero."},{"txt":"\"Vi la frase en una imagen con su foto, así que es suya\".","g1":"Sin obra y sin capítulo no entra: si no aparece en ninguna de las dos obras, la frase no es de Smith aunque lleve su cara al lado, y esa es la forma más pura de fuente inflada.","g2":"Se corrige buscándola en el texto y anotando el resultado, aunque el resultado sea que no está."},{"txt":"\"El libro de la moral era cosa de juventud, ya superada\".","g1":"Es falso y hay un dato que lo cierra: Smith siguió corrigiendo la Teoría de los sentimientos morales hasta su sexta edición, la de 1790, catorce años después de la Riqueza de las naciones.","g2":"Se corrige citando las dos obras con sus años y el dato de la sexta edición."},{"txt":"\"El argumento de Stigler no vale la pena ni contestarlo\".","g1":"Es la regla del acero al revés: Stigler no niega ningún pasaje, discute si el autor era coherente, y esa es una objeción legítima que hay que responder leyendo la obra completa.","g2":"Se corrige reconstruyendo su argumento en su forma más fuerte antes de contestarlo."}];

const critDecisionBank=["El tío ya cerró la sobremesa con la mano invisible: ¿qué se contesta en tres renglones, sin quedar de sabelotodo?","El primo dijo que Smith fue el padre del neoliberalismo: ¿qué se le contesta, y por qué el test corta en las dos direcciones?","Las tres pulperías subieron el precio la misma semana: ¿qué cita sirve aquí, qué NO prueba esa cita, y qué pregunta la reemplaza?","Alguien dice que los patrones nunca se coordinan: ¿qué pasaje se trae, y qué cuidado hay que tener con un pasaje que le da la razón a uno?","Jael trajo una frase de una imagen: ¿qué procedimiento se sigue, y qué se hace si la frase no aparece en ningún libro?","Angelly pregunta qué decía Smith de los impuestos: ¿qué se le contesta, y qué freno se pone para no convertirlo en bandera propia?","Alguien quiere usar esta etapa para señalar a una persona con pleito abierto: ¿qué dice la regla de selección de la materia y cómo se escribe el caso como categoría?","La casa parafrasea a Smith en sus misiones: ¿qué se declara, qué se indica en vez de la página, y qué señal obligaría a corregir una misión publicada?"];
const critDecisionGuide="La decisión correcta sigue siempre el mismo orden, y el orden es el método. Primero se copia la frase tal como llegó, sin arreglarla, porque arreglarla ya es interpretarla. Segundo se busca la direccion: obra y año, y libro y capitulo si se puede. Con Smith las direcciones que hay que tener de memoria son cuatro: la mano invisible en el libro IV capitulo 2, donde aparece UNA sola vez en una obra de cinco libros; el carnicero en el libro I capitulo 2; los del mismo oficio y su conspiracion contra el publico en el libro I capitulo 10; y los patrones coordinados tacitamente para no subir salarios en el libro I capitulo 8, el mismo capitulo donde dice que ninguna sociedad puede ser floreciente y feliz si la mayor parte de sus miembros son pobres y miserables. Y si la frase no aparece en ninguna de las dos obras, eso tambien es un resultado, y de los buenos. Tercero se lee el parrafo entero y se cuenta de que estaba hablando el autor ahi, que casi nunca es lo que la frase suelta sugiere. Cuarto, y es la pregunta que hace todo el trabajo, se trae la contracita: la frase del mismo autor que apunta al lado contrario, con su direccion. Esa es la prueba de lectura, porque cualquiera encuentra la que le da la razon y solo quien leyo encuentra la que se la quita, y funciona igual contra el devoto y contra el detractor. Quinto se dice que edicion o traduccion se esta usando y si la cita es literal o parafraseada: la academica es la Glasgow Edition, que Oxford publica desde 1976, y esta casa declara sus parafrasis y da libro y capitulo en vez de fingir una pagina. Se cierra diciendo que se sigue de todo eso para la discusion que habia: que ya no se puede decir, que queda en pie y que habria que mirar ahora. Y encima de todo va el aviso que impide el error simetrico, que en esta etapa es el mas dulce: descubrir que a un autor lo citan mal no lo vuelve aliado de uno, y un clasico leido entero casi nunca cabe en un bando.";

const critCompareBank=[{"a":"Decir «libro IV, capítulo 2, y aparece una sola vez en toda la obra».","b":"Decir «lo dijo Adam Smith».","ga":"Caso A: da la dirección exacta, así que cualquiera puede ir a leer el párrafo y discutirlo, y de paso queda claro cuánto peso tiene la frase en la obra.","gb":"Caso B: usa el prestigio del nombre y no ofrece nada verificable; funciona para cerrar la conversación, que es para lo que se dijo.","gr":"La diferencia no es de erudición sino de intención: una cita usada como fuente quiere ser comprobada y una usada como escudo no."},{"a":"Traer el carnicero y, al lado, la conspiración de los del mismo oficio.","b":"Traer solo el carnicero.","ga":"Caso A: demuestra lectura, porque la segunda frase le estorba a quien la trae, y deja la discusión en el terreno del texto.","gb":"Caso B: puede repetirse sin haber abierto el libro, porque esa frase circula sola en carteles e imágenes.","gr":"La contracita es la prueba de lectura de esta etapa, y funciona igual contra el devoto y contra el detractor."},{"a":"Decir «esto es paráfrasis, y el texto exacto está en la Glasgow Edition».","b":"Poner la frase entre comillas como si fuera traducción literal.","ga":"Caso A: es honrado y comprobable: quien quiera el texto exacto sabe dónde buscarlo, y quien lea sabe qué está leyendo.","gb":"Caso B: finge una precisión que no tiene, y si alguien va a comprobarlo no encontrará esas palabras, con lo cual la casa pierde lo único que le importa.","gr":"Declarar la paráfrasis cuesta un renglón y compra toda la credibilidad de la misión."},{"a":"Contestar a Stigler reconstruyendo su argumento antes de responderlo.","b":"Descartar a Stigler por ser de Chicago.","ga":"Caso A: es la regla del acero de esta ruta, y además obliga a leer más y mejor, porque su objeción es sobre coherencia y no sobre datos.","gb":"Caso B: descalifica por procedencia, que es lo mismo que hacen los que citan a Smith sin leerlo, con la bandera cambiada.","gr":"Y hay un detalle que remata: Viner también era de Chicago, y su resultado va en la dirección contraria a la de Stigler."}];

const critCauseBank=[{"cause":"Se cita a un clásico sin obra, año ni capítulo.","guide":"Sin dirección no hay nada que comprobar, y una cita que no puede comprobarse está funcionando como escudo y no como fuente. La prueba práctica cabe en una pregunta amable: pásame de dónde es, para leerlo completo. Quien usa la cita como fuente la da con gusto; quien la usa como escudo cambia de tema."},{"cause":"Se recorta la frase de su párrafo.","guide":"Casi ninguna frase famosa dice, en su contexto, lo que dice suelta. La mano invisible está en un párrafo sobre la preferencia por invertir en el propio país, dentro de un libro dedicado a demoler el sistema mercantil. Leer el párrafo no es un lujo de erudito: es la diferencia entre citar al autor y citar a su fama."},{"cause":"No se trae nunca la contracita.","guide":"Es la señal más limpia de que no se ha leído. Cualquiera encuentra la frase que le da la razón, porque esa circula sola; solo quien leyó encuentra la que se la quita. Con Smith el ejercicio es fácil y demoledor: al carnicero del libro I capítulo 2 se le opone el capítulo 10, y a los impuestos del libro V se les opone el carnicero."},{"cause":"Se cuelga a un autor una palabra posterior a su muerte.","guide":"Es un problema de calendario antes que de ideas, y por eso se resuelve rápido: Smith murió en 1790 y la palabra que se le cuelga se acuñó y se popularizó mucho después. Eso no significa que no se pueda discutir su influencia, significa que hay que discutirla con fechas y no con etiquetas. La historia de esa palabra tiene su propio expediente en la etapa 6."},{"cause":"Se convierte al autor bien citado en aliado propio.","guide":"Es el error simétrico de esta etapa y aparece justo cuando uno acaba de aprender lo demás, que es lo que lo hace peligroso. Que Smith pidiera impuestos y educación pública no lo vuelve socialista, igual que la frase del carnicero no lo vuelve un panfleto. Un clásico leído entero casi nunca cabe en un bando, y esa incomodidad es la señal de que se leyó bien."},{"cause":"Se cita en paráfrasis y se presenta como traducción literal.","guide":"Es una falta pequeña que cuesta muy caro, porque es exactamente la que la etapa enseña a cazar. Si alguien va a comprobar el pasaje y no encuentra esas palabras, pierde la confianza en todo lo demás, y con razón. La regla de la casa es barata: se declara la paráfrasis, se da libro y capítulo en vez de una página inventada, y se nombra la edición académica para quien quiera el texto exacto."}];
const critEffectBank=[{"effect":"La sobremesa terminó con la cita puesta de pie y sin pelea.","guide":"Se dijo que la frase es real, que aparece una sola vez, en el libro IV capítulo 2, y que ese párrafo habla de que el comerciante prefiere invertir en su propio país. Y se añadió la contracita del libro I capítulo 10, la de los del mismo oficio y la conspiración contra el público. Nadie quedó humillado y la conversación pasó del prestigio al texto, que es donde se puede discutir."},{"effect":"Al primo se le contestó con el mismo test, y no con la bandera contraria.","guide":"Se le mostró que llamar a Smith padre del neoliberalismo es primero un problema de calendario, porque murió en 1790 y la palabra vino mucho después. Y se le pidió lo mismo que al tío: obra, año y capítulo. El test corta en las dos direcciones y por eso sirve; si solo cortara hacia un lado sería otra bandera."},{"effect":"El caso de las tres pulperías quedó bien escrito en el expediente.","guide":"Se trajo el pasaje del libro I capítulo 10, y se anotó expresamente lo que ese pasaje no prueba: no demuestra que las tres se pusieran de acuerdo, y decir lo contrario sería el vicio de la etapa. Lo que hizo fue cambiar la pregunta, de si son malas personas a cuántos venden aquí y qué tan fácil es coordinarse, que es una pregunta que se contesta mirando la cuadra."},{"effect":"Jael aprendió el procedimiento para las frases de imagen, y sin regaño.","guide":"Primero la dirección: si la imagen no dice obra ni capítulo, eso ya es un dato sobre la imagen. Después la búsqueda en el texto, que está publicado. Y el resultado que decide: si no aparece en ninguna de las dos obras, la frase no es de Smith aunque lleve su cara. La regla quedó escrita: una frase sin obra y sin capítulo no entra en un trabajo, aunque sea bonita."},{"effect":"La casa dejó por escrito cómo cita a Smith en sus misiones.","guide":"Toda cita lleva obra, año y capítulo; lo parafraseado se declara parafraseado y por eso se da libro y capítulo en vez de una página; el acero del bando contrario entra en su mejor versión, que aquí es Stigler; y las lecturas de estilo llevan su etiqueta de pastiche. Y la señal que obligaría a corregir: si una familia busca un pasaje citado aquí y no lo encuentra donde dice, se corrige la misión."},{"effect":"Angelly obtuvo una respuesta que sirve para discutir y no para ganar.","guide":"Se le mostró el libro V, con los tres deberes del soberano y el pasaje del capítulo 2 sobre que los ricos podrían contribuir algo más que en proporción a su renta. Y se le puso el freno en la misma frase: eso no convierte a Smith en partidario de nada de hoy. Lo que hace es sacar la discusión de las etiquetas y llevarla a la pregunta útil, que es cuáles impuestos, para qué y con qué factura, tal como enseñó la etapa 2."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🪶 La cita sobre la mesa · Forma ${cf} · El escocés dorado · Ruta del Expediente Dorado`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. La cita sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿De qué obra y de qué año es esta frase, y de qué libro y capítulo? Cuenta qué dice el párrafo completo alrededor, trae la contracita del mismo autor con su dirección, di qué edición se usa y si la cita es literal o parafraseada, y explica qué se sigue de todo eso para lo que se estaba discutiendo.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos se puede ir a comprobar en el libro y cuál solo se puede repetir? 2. ¿Por qué uno demuestra lectura y el otro no?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La cita sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. La cita sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿De qué obra y de qué año es esta frase, y de qué libro y capítulo? Cuenta qué dice el párrafo completo alrededor, trae la contracita del mismo autor con su dirección, di qué edición se usa y si la cita es literal o parafraseada, y explica qué se sigue de todo eso para lo que se estaba discutiendo.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos se puede ir a comprobar en el libro y cuál solo se puede repetir? 2. ¿Por qué uno demuestra lectura y el otro no?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La cita sobre la mesa El escocés dorado · Ruta del Expediente Dorado · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3f6212;background:#f7fee7;color:#3f6212;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3f6212;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3f6212;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#f7fee7;border-left:3px solid #3f6212;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#f7fee7;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#f7fee7;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3f6212;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3f6212;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La cita sobre la mesa · El escocés dorado · Ruta del Expediente Dorado · Etapa 5 · Estudio Mayor</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La cita sobre la mesa · El escocés dorado · Ruta del Expediente Dorado · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1759","icon":"❤️","label":"El libro olvidado","text":"Smith publica <strong>«La teoría de los sentimientos morales»</strong>, sobre cómo nos importa la suerte de los demás y sobre el <strong>espectador imparcial</strong>, ese juez de dentro con el que uno se mira desde fuera. Etiqueta: <strong>fuente primaria, y el gran olvidado</strong>."},{"y":"1776","icon":"💰","label":"La riqueza de las naciones","text":"Aparece la obra en <strong>cinco libros</strong>. En el <strong>I, capítulo 2</strong> está el carnicero; en el <strong>I, capítulo 10</strong>, la conspiración de los del mismo oficio; en el <strong>IV, capítulo 2</strong>, la <strong>única</strong> aparición de la mano invisible; y el <strong>V</strong> trata de lo que debe hacer el Estado. Etiqueta: <strong>fuente primaria</strong>."},{"y":"1778","icon":"⚓","label":"La ironía de la aduana","text":"Smith empieza a trabajar como <strong>comisionado de aduanas en Edimburgo</strong>: el crítico más famoso del sistema mercantil pasa sus últimos años cobrando por hacer cumplir aranceles. Del dato responde la biografía estándar, la de <strong>Ross (1995)</strong>."},{"y":"1790","icon":"📅","label":"La sexta edición, y la muerte","text":"Sale la <strong>sexta edición</strong> de «La teoría de los sentimientos morales», corregida por su autor, el <strong>mismo año en que muere</strong>. Catorce años después de la Riqueza de las naciones. Etiqueta: <strong>el dato que desarma la excusa</strong> de la obra de juventud superada."},{"y":"1927","icon":"📐","label":"Viner cataloga las excepciones","text":"En el <strong>Journal of Political Economy</strong>, <strong>Jacob Viner</strong> publica <strong>«Adam Smith and Laissez Faire»</strong> y cataloga una por una las excepciones que Smith admite. Etiqueta: <strong>clásico de la interpretación</strong>, y de un economista de Chicago: no del bando al que le convenía."},{"y":"1971","icon":"🔩","label":"Stigler, el acero","text":"En <strong>«Smith's Travels on the Ship of State»</strong>, <strong>George Stigler</strong> sostiene que las excepciones intervencionistas <strong>no encajan con el propio análisis del interés propio</strong>: si los comerciantes capturan el mercado, los funcionarios capturan el Estado. Etiqueta: <strong>el acero</strong>, y se contesta leyendo."},{"y":"1976","icon":"📗","label":"La edición de Glasgow","text":"Oxford empieza a publicar la <strong>Glasgow Edition of the Works and Correspondence of Adam Smith</strong>. Etiqueta: <strong>la edición académica de referencia</strong>. Es la que se cita cuando hace falta el texto exacto y no una paráfrasis."},{"y":"1995","icon":"🧑‍🏫","label":"La vida, documentada","text":"<strong>Ian Simpson Ross</strong> publica <strong>«The Life of Adam Smith»</strong>, la <strong>biografía estándar</strong>. De ahí salen la cátedra de Filosofía Moral en Glasgow, el puesto de aduanas y la orden de <strong>quemar sus manuscritos inéditos</strong> antes de morir."},{"y":"2001","icon":"📜","label":"Rothschild sigue la pista de la frase","text":"En <strong>«Economic Sentiments»</strong>, <strong>Emma Rothschild</strong> rastrea cómo una expresión menor, y hasta irónica, se volvió el emblema de una doctrina entera. Su conclusión: <strong>la fama de la frase la construyeron los lectores, no el autor</strong>. Etiqueta: <strong>historia intelectual</strong>."},{"y":"Hoy","icon":"🪶","label":"El test de la fecha y del libro","text":"De todo lo anterior sale la herramienta de la etapa, y no sirve solo para Smith: <strong>obra y año, párrafo entero, contracita, edición y qué se sigue de eso</strong>. La tercera pregunta es la que separa a un lector de un hincha, porque <strong>solo quien leyó puede traer la frase que le estorba</strong>."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(prueba){sfx(prueba?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(prueba){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🪶</span><span class="ms-text"><strong>Quedó anotada la cita con su dirección:</strong> «la expresión aparece <strong>una sola vez</strong> en «La riqueza de las naciones», de 1776, en el <strong>libro IV, capítulo 2</strong>, y ese párrafo habla de que el comerciante prefiere invertir en su propio país».</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">↔️</span><span class="ms-text"><strong>Y debajo, la contracita, que es la prueba de lectura:</strong> en el <strong>libro I, capítulo 10</strong>, el mismo autor escribe que los del mismo oficio raras veces se reúnen sin que la charla acabe en una conspiración contra el público. <strong>Y el freno, escrito antes de que dé gusto:</strong> esto no convierte a Smith en aliado de nadie; un clásico leído entero casi nunca cabe en un bando.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🖼️</span><span class="ms-text"><strong>Quedó la frase de bandera:</strong> «Adam Smith dijo que el mercado se arregla solo». Suena a erudición, cierra la sobremesa y nadie va a ir a comprobarla, que es justo para lo que se usó.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🪤</span><span class="ms-text"><strong>El costo llega en dos partes:</strong> se le atribuye al autor lo que dijo su fama, y de camino queda enseñado que en esta casa <strong>una cita se repite sin preguntar de qué libro es</strong>. Se tacha y se reescribe con la obra, el año, el libro y el capítulo, y con la frase suya que estorba.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"libros":{"nombre":"Dos libros, una cabeza","icon":"📚","estructura":{"title":"Qué dice","info":"• Smith escribió <strong>dos</strong> obras, y el que casi nadie menciona es el primero<br>• <strong>1759:</strong> «La teoría de los sentimientos morales», con el <strong>espectador imparcial</strong><br>• <strong>1776:</strong> «La riqueza de las naciones», en cinco libros"},"funcion":{"title":"Cómo se reconoce","info":"• Cuando alguien habla de «Smith» y solo conoce <strong>una</strong> de las dos obras<br>• Cuando dice que la moral era <strong>cosa de juventud</strong><br>• Ahí entra el dato: <strong>la sexta edición es de 1790</strong>, el año en que murió"},"enfermedades":{"title":"Dónde se cae","info":"• Quedarse con <strong>un solo libro</strong>, que es leer a otra persona<br>• Creer que el <strong>orden</strong> de publicación indica abandono<br>• Y olvidar que el <strong>libro V</strong> de la Riqueza trata del Estado"},"cuidados":{"title":"En esta casa","info":"• Las <strong>dos obras entran juntas</strong>, con su año, y la Teoría con su sexta edición<br>• Los datos del hombre vienen de <strong>Ross (1995)</strong>, la biografía estándar<br>• Y la <strong>Glasgow Edition</strong> se nombra para quien quiera el texto exacto"}},"carnicero":{"nombre":"La frase del carnicero","icon":"🥩","estructura":{"title":"Qué dice","info":"• <strong>Libro I, capítulo 2:</strong> la cena no viene de la bondad sino del propio interés<br>• Que el sistema <strong>no necesita santos</strong> para alimentar una ciudad<br>• Es un hallazgo genuino, y esta casa lo trata con respeto"},"funcion":{"title":"Cómo se reconoce","info":"• Se distingue <strong>lo que afirma</strong> de <strong>lo que se le cuelga</strong><br>• No dice que la bondad no exista: el autor escribió un libro sobre eso<br>• Y no dice que <strong>no hagan falta reglas</strong>, que es el libro V"},"enfermedades":{"title":"Dónde se cae","info":"• Confundir <strong>«no hace falta bondad»</strong> con <strong>«no hace falta ley»</strong><br>• Citarla y detenerse, sin llegar al capítulo <strong>8</strong> ni al <strong>10</strong><br>• Y usarla como final de conversación en vez de como punto de partida"},"cuidados":{"title":"En esta casa","info":"• Va siempre con su <strong>contracita</strong>, que está en el mismo libro I<br>• Y con la frase del capítulo 8: <strong>ninguna sociedad floreciente con la mayoría pobre</strong><br>• El corte se señala en <strong>los dos bandos</strong>, porque los dos lo hacen"}},"incomodo":{"nombre":"El Smith incómodo","icon":"😬","estructura":{"title":"Qué dice","info":"• <strong>I, 10:</strong> los del mismo oficio y la conspiración contra el público<br>• <strong>I, 8:</strong> los patrones coordinados tácitamente para no subir salarios<br>• <strong>V, 2 y V, 1:</strong> los ricos contribuyendo algo más, y la escuela pública"},"funcion":{"title":"Cómo se reconoce","info":"• Es la parte del libro que <strong>no está en los carteles</strong><br>• Y el <strong>libro IV</strong> entero, que demuele el sistema mercantil y los monopolios<br>• Con los <strong>tres deberes del soberano</strong>: defensa, justicia y obras públicas"},"enfermedades":{"title":"Dónde se cae","info":"• Descubrirlo y <strong>declararlo aliado propio</strong>, que es el error simétrico<br>• Usarlo para <strong>probar cosas de hoy</strong> que el texto no prueba<br>• Y olvidar que <strong>Viner ya lo había catalogado en 1927</strong>: no es un hallazgo nuevo"},"cuidados":{"title":"En esta casa","info":"• Cada pasaje entra <strong>con su libro y su capítulo</strong>, para que se pueda comprobar<br>• Con <strong>el acero de Stigler (1971)</strong> al lado, que discute la coherencia<br>• Y con el freno escrito: <strong>un clásico entero casi nunca cabe en un bando</strong>"}},"test":{"nombre":"El test de la fecha y del libro","icon":"🔬","estructura":{"title":"Qué dice","info":"• Cinco preguntas: <strong>obra y año, párrafo, contracita, edición y consecuencia</strong><br>• Sirve para <strong>cualquier clásico</strong>, no solo para Smith<br>• Y termina en la hoja de la cita, que se llena antes de repetir nada"},"funcion":{"title":"Cómo se reconoce","info":"• La tercera pregunta es la que hace el trabajo: <strong>la contracita</strong><br>• Porque cualquiera halla la frase que le da la razón<br>• Y <strong>solo quien leyó</strong> halla la que se la quita"},"enfermedades":{"title":"Dónde se cae","info":"• Aplicarlo <strong>en una sola dirección</strong>, contra el bando ajeno<br>• Pedir la dirección y no leer el <strong>párrafo</strong><br>• Y presentar una <strong>paráfrasis</strong> entre comillas como si fuera literal"},"cuidados":{"title":"En esta casa","info":"• El test <strong>corta en las dos direcciones</strong>, contra el devoto y contra el detractor<br>• Las citas de esta misión van <strong>parafraseadas y declaradas como tal</strong><br>• Y con <strong>libro y capítulo</strong> en vez de una página inventada"}}};
let labParte='libros',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

